import sys

def is_valid_euler_tour(tour, n):
    if len(tour) != 2 * n - 1:
        return False
    degree = [0] * (n + 1)
    for i in range(len(tour)):
        if tour[i] > 0:
            degree[tour[i]] += 1
    for d in degree[1:]:
        if d % 2 != 0:
            return False
    return True

def reconstruct_euler_tour(n, a):
    degree = [0] * (n + 1)
    for x in a:
        if x > 0:
            degree[x] += 1

    if any(d % 2 != 0 for d in degree[1:]):
        return "no"

    stack = []
    tour = []
    current = 1
    for i in range(2 * n - 1):
        if a[i] == 0:
            while degree[current] == 0:
                current = stack.pop()
            a[i] = current
        tour.append(a[i])
        degree[a[i]] -= 1
        if degree[a[i]] > 0:
            stack.append(a[i])
            current = a[i]

    if not is_valid_euler_tour(tour, n):
        return "no"

    return "yes\n" + " ".join(map(str, tour))

